with cleaned as (select id, customer_id, browser, started_at, day(started_at) as started_at_day, coalesce(browser, 'N/A') as browser_filled from sessions where started_at >= date '2023-09-01' and country is not null), with_gaps as (select *, case when lag(started_at) over (partition by customer_id order by started_at, id) is null or started_at > lag(started_at) over (partition by customer_id order by started_at, id) + interval '7' day then 1 else 0 end as new_group_flag from cleaned), sessionized as (select *, sum(new_group_flag) over (partition by customer_id order by started_at, id rows between unbounded preceding and current row) as session_id from with_gaps) select case when started_at_day >= 67 then 'LARGE' else 'SMALL' end as started_at_day_tier, count(*) as event_count, (unix_timestamp(max(started_at)) - unix_timestamp(min(started_at))) / 60 as span_minutes from sessionized group by case when started_at_day >= 67 then 'LARGE' else 'SMALL' end order by span_minutes desc;
